//! The showcase design as data: parts, pin-to-net assignments and positions.
//!
//! An original battery-powered environment sensor node, 53 parts on three
//! schematic pages. Changing a position here moves the part in the next
//! generated file; nothing else in the generator knows the layout.
//!
//! # Rules
//! - Net names are the only connectivity; every pin of a part is listed once.
//! - Schematic coordinates are millimetres on a 2.54 grid; board coordinates
//!   are millimetres from the top-left corner of the board.
//!
//! # Dependencies
//! - xtask/src/showcase/parts.rs
//!
//! # Do not
//! - Name a real manufacturer part; values stay generic.

/// One placed part.
pub struct Part {
    pub reference: &'static str,
    pub symbol: &'static str,
    pub value: &'static str,
    pub footprint: &'static str,
    /// Schematic page index: 0 power, 1 compute, 2 sensors and indicators.
    pub sheet: usize,
    pub sch: (f64, f64),
    pub sch_rot: f64,
    /// Body height in millimetres for the 3D view.
    pub height: f64,
    /// Short description kept as a component property for the bill of materials.
    pub note: &'static str,
}

#[allow(clippy::too_many_arguments)]
const fn part(
    reference: &'static str,
    symbol: &'static str,
    value: &'static str,
    footprint: &'static str,
    sheet: usize,
    sch: (f64, f64),
    sch_rot: f64,
    height: f64,
    note: &'static str,
) -> Part {
    Part {
        reference,
        symbol,
        value,
        footprint,
        sheet,
        sch,
        sch_rot,
        height,
        note,
    }
}

