/// Pairs of pins joined by a drawn wire on the schematic instead of two labels.
/// A pin as a reference and a pin number.
pub type PinRef = (&'static str, &'static str);

pub const DIRECT: &[(PinRef, PinRef)] = &[
    (("R4", "2"), ("D1", "1")),
    (("R10", "2"), ("D3", "1")),
    (("R11", "2"), ("D4", "1")),
    (("R12", "2"), ("D5", "1")),
    (("R13", "2"), ("D6", "1")),
    (("R14", "2"), ("D7", "1")),
    (("R15", "2"), ("D8", "1")),
];

